INSERT INTO disclosure_config_version (jurisdiction, transaction_type, use_class, version, items, status, note) VALUES
  ('NSW', 'sale', 'commercial', 1, '[{"key":"nsw_comm_sale_vendor_disclosure","label":"Vendor disclosure for commercial land","description":"The vendor''s disclosure of title, encumbrances, zoning and planning controls, rates and charges, and notices or orders affecting the property, given to the buyer before the contract is signed.","legalRef":"Conveyancing (Sale of Land) Regulation 2022 (NSW), Sch 1","notApplicableAllowed":false},{"key":"nsw_comm_sale_title_search","label":"Current title search","description":"A current title search for the property, showing the registered owner, easements, covenants and other interests.","legalRef":"Conveyancing (Sale of Land) Regulation 2022 (NSW), Sch 1","notApplicableAllowed":false},{"key":"nsw_comm_sale_scheme","label":"Strata or scheme information","description":"For a lot in a strata, owners corporation or community scheme: the levies, by-laws, insurance and financial position of the scheme. Mark not applicable if the lot is not in a scheme.","legalRef":"Strata Schemes Management Act 2015 (NSW)","propertyTypes":["unit","townhouse","other"],"notApplicableAllowed":true}]'::jsonb, 'draft', 'Draft by engineering from public sources on 18 Nov 2026. Compliance and counsel must confirm items, section numbers and wording before approving.'),
  ('NSW', 'rent', 'residential', 1, '[{"key":"nsw_rent_agreement","label":"Written tenancy agreement","description":"The written residential tenancy agreement in the form the state requires, given to the tenant, with the prescribed information statement where one applies.","legalRef":"Residential Tenancies Act 2010 (NSW)","notApplicableAllowed":false},{"key":"nsw_rent_condition_report","label":"Condition report","description":"A condition report on the property at the start of the tenancy, given to the tenant to check and return.","legalRef":"Residential Tenancies Act 2010 (NSW)","notApplicableAllowed":false},{"key":"nsw_rent_bond","label":"Bond lodgement","description":"The rental bond is lodged with the state''s rental bond authority, not held by the owner. Provide the lodgement receipt or number once the bond is paid.","legalRef":"Residential Tenancies Act 2010 (NSW)","notApplicableAllowed":false},{"key":"nsw_rent_smoke_alarms","label":"Smoke alarm compliance","description":"Evidence that smoke alarms are installed and working as the state requires for rental properties.","legalRef":"Residential Tenancies Act 2010 (NSW); state smoke alarm requirements","notApplicableAllowed":false}]'::jsonb, 'draft', 'Draft by engineering from public sources on 18 Nov 2026. Compliance and counsel must confirm items, section numbers and wording before approving.'),
  ('NSW', 'rent', 'commercial', 1, '[{"key":"nsw_comm_rent_retail_lease","label":"Retail lease disclosure statement and draft lease","description":"For a retail shop lease: the lessor''s disclosure statement and a copy of the proposed lease, given to the prospective tenant before the lease is entered into. Mark not applicable if the retail lease law does not apply (for example the premises or tenant are outside its scope).","legalRef":"Retail Leases Act 1994 (NSW)","propertyTypes":["retail"],"notApplicableAllowed":true}]'::jsonb, 'draft', 'Draft by engineering from public sources on 18 Nov 2026. Compliance and counsel must confirm items, section numbers and wording before approving.'),
